from __future__ import annotations

from collections.abc import Callable
from typing import Any

import streamlit as st

from optichub.grpc_client import ModuleInfo, configure_module, start_module, stop_module


def tab_lsm_watcher(
    host: str,
    port: int,
    info: ModuleInfo | None,
    cfg: dict[str, Any],
    running: bool,
    can_stop: bool,
    key: Callable[[str], str],
) -> None:
    watch_path = st.text_input(
        "Watch path",
        value=str(cfg.get("watch_path", "")),
        key=key("m_lw_path"),
    )
    redis_queue_name = st.text_input(
        "Redis queue name (RQ)",
        value=str(cfg.get("redis_queue_name", "")),
        key=key("m_lw_queue"),
    )
    poll_interval = st.number_input(
        "Poll interval (seconds)",
        min_value=1,
        value=int(cfg.get("poll_interval", 5)),
        step=1,
        key=key("m_lw_poll"),
    )
    stability_seconds = st.number_input(
        "Stability (seconds)",
        min_value=0,
        value=int(cfg.get("stability_seconds", 15)),
        step=1,
        key=key("m_lw_stab"),
    )
    force_resend = st.checkbox(
        "Force resend",
        value=bool(cfg.get("force_resend", False)),
        key=key("m_lw_force"),
    )
    project_name = st.text_input(
        "Project name",
        value=str(cfg.get("project_name", "")),
        key=key("m_lw_proj"),
    )
    slice_offset = st.number_input(
        "Slice offset",
        value=int(cfg.get("slice_offset", 0)),
        step=1,
        key=key("m_lw_slice_off"),
    )
    payload = {
        "watch_path": watch_path.strip(),
        "redis_queue_name": redis_queue_name.strip(),
        "poll_interval": int(poll_interval),
        "stability_seconds": int(stability_seconds),
        "force_resend": bool(force_resend),
        "project_name": project_name.strip(),
        "slice_offset": int(slice_offset),
    }

    c1, c2 = st.columns(2)
    with c1:
        if st.button("Start", type="primary", disabled=running, key=key("m_lw_start")):
            ok, msg = start_module(host, port, module="lsm_watcher", config=payload)
            if ok:
                st.success(msg or "started")
                st.rerun()
            else:
                st.error(msg)
    with c2:
        if st.button("Stop", disabled=not can_stop, key=key("m_lw_stop")):
            ok, msg = stop_module(host, port, module="lsm_watcher")
            if ok:
                st.success(msg or "stopped")
                st.rerun()
            else:
                st.error(msg)

    if st.button("Apply config (restart module)", disabled=not running, key=key("m_lw_apply")):
        ok, msg = configure_module(host, port, module="lsm_watcher", config=payload)
        if ok:
            st.success(msg or "reconfigured")
            st.rerun()
        else:
            st.error(msg)


